const fibfib = (n) => {
  if (n < 0) throw new Error('n must be non-negative');
  const memo = new Array(n + 1).fill(undefined);
  memo[0] = 0;
  if (n >= 1) memo[1] = 0;
  if (n >= 2) memo[2] = 1;
  for (let i = 3; i <= n; i++) {
    memo[i] = memo[i - 1] + memo[i - 2] + memo[i - 3];
  }
  return memo[n];
};

