const pluck = (arr) => {
  if (!Array.isArray(arr) || arr.length === 0) return [];
  let minVal = Infinity;
  let minIdx = -1;
  for (let i = 0; i < arr.length; i++) {
    const val = arr[i];
    if (val % 2 === 0) {
      if (val < minVal || (val === minVal && i < minIdx)) {
        minVal = val;
        minIdx = i;
      }
    }
  }
  return minVal === Infinity ? [] : [minVal, minIdx];
};

