  const freq = new Map();
  for (const num of lst) {
    freq.set(num, (freq.get(num) || 0) + 1);
  }
  let best = -1;
  for (const [num, count] of freq.entries()) {
    if (count >= num && num > best) {
      best = num;
    }
  }
  return best;
};

