const strangeSortList = (lst) => {
  if (!Array.isArray(lst) || lst.length === 0) return [];
  const sorted = [...lst].sort((a, b) => a - b);
  const result = [];
  let left = 0;
  let right = sorted.length - 1;
  let takeMin = true;
  while (left <= right) {
    if (takeMin) {
      result.push(sorted[left]);
      left++;
    } else {
      result.push(sorted[right]);
      right--;
    }
    takeMin = !takeMin;
  }
  return result;
};

