const willItFly = (q, w) => {
  const isPalindrome = (arr) => {
    for (let i = 0; i < Math.floor(arr.length / 2); i++) {
      if (arr[i] !== arr[arr.length - 1 - i]) return false;
    }
    return true;
  };

  if (!isPalindrome(q)) return false;

  const sum = q.reduce((acc, val) => acc + val, 0);
  return sum <= w;
};

